define('core/encoder/time',['moment'], function (moment) {
  'use strict';

  moment = moment && Object.prototype.hasOwnProperty.call(moment, 'default') ? moment['default'] : moment;
  var format = 'HH:mm:ss';
  var time = {
    encode(modelValue) {
      var seconds = parseInt(modelValue, 10);
      if (isNaN(seconds)) {
        seconds = 0;
      }
      var time = moment.duration(seconds, 'seconds');
      var h = time.get('hours') >= 10 ? time.get('hours') : "0".concat(time.get('hours'));
      var m = time.get('minutes') >= 10 ? time.get('minutes') : "0".concat(time.get('minutes'));
      var s = time.get('seconds') >= 10 ? time.get('seconds') : "0".concat(time.get('seconds'));
      return "".concat(h, ":").concat(m, ":").concat(s);
    },
    decode(nodeValue) {
      var time = moment(nodeValue, format);
      return time.seconds() + time.minutes() * 60 + time.hours() * 3600;
    }
  };
  return time;
});
